// Organizational Leadership Practice Test 4. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items. HOSA facts follow the Valus Organizational
// Leadership lessons, which summarize the HOSA Handbook (Sections A–C), the HOSA website and
// The First Fifty Years 1976–2026; parliamentary items follow RONR In Brief.
import {q, mix} from './q.js';
const HB='HOSA Handbook, Sections A–C', WEB='HOSA website (Voting Delegate resources)', FFY='HOSA, The First Fifty Years 1976–2026', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const VD='Voting Delegate Role and Responsibilities', PP='Parliamentary Procedure', INC='HOSA Inc.', ORG='Organizational Structure of HOSA', HIST='History of HOSA', EC='Positions and Responsibilities of the Executive Council', MEM='Membership';

export default {
 id:'organizational-leadership-4',
 event:'Organizational Leadership',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the HOSA Handbook (Sections A–C), the HOSA website, The First Fifty Years 1976–2026 and Robert’s Rules of Order Newly Revised In Brief',
 plan:[{area:VD,weight:24},{area:PP,weight:24},{area:INC,weight:16},{area:ORG,weight:12},{area:HIST,weight:12},{area:EC,weight:8},{area:MEM,weight:4}],
 questions:mix([
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 25,000 members receive?','14',['12','13','15'],'A','4 delegates cover 3,001–5,000 members, and one is added per 2,000 more: (25,000 − 5,000) ÷ 2,000 = 10 more, so 23,001–25,000 members earn 14.',WEB),
  q(VD,'What is the smallest membership that earns a chartered association 2 voting delegates?','101 members',['26 members','100 members','1,001 members'],'B','The table gives 1 delegate for 25–100 members and 2 delegates for 101–1,000 members, so 101 is the lowest membership with two delegates.',WEB),
  q(VD,'A chartered association with 4,800 members gains 400 more. How does its delegate count change?','It rises from 4 to 5',['It stays at 4 delegates','It rises from 3 to 4','It rises from 5 to 6'],'C','3,001–5,000 members earn 4 delegates and 5,001–7,000 earn 5, so growing to 5,200 members crosses the boundary and adds one delegate.',WEB),
  q(VD,'Which two items about Executive Council applicants must delegates review before ILC?','Their resumes and their YouTube videos',['Their report cards and their test scores','Their chapter budgets and their photos','Their state rankings and their essays'],'D','Before ILC, delegates review the Voting Delegate Packet plus the Executive Council applicants’ resumes and YouTube videos posted on the HOSA website.',WEB),
  q(VD,'A delegate has very little material on one candidate. What is the fairest approach?','Judge on the evidence available, not on assumptions',['Rate that candidate lowest for missing details','Fill the gaps with what others have guessed','Skip that office’s vote entirely to be safe'],'A','If materials are limited, delegates focus on the evidence available rather than filling gaps with assumptions; consistent notes keep comparisons fair.',WEB),
  q(VD,'During debate, a delegate disagrees strongly with another state’s delegate. What is the best conduct?','Debate the issue respectfully through the chair',['Address the other delegate by name directly','Leave the session until the vote is taken','Ask the chair to remove that delegate’s vote'],'B','Delegates respect other chartered associations’ views; speaking through the chair about issues, not individuals, keeps healthy debate respectful.',WEB),
  q(VD,'Why should a delegate pay close attention to ballot instructions at orientation?','So their vote is counted as they intended',['So they can vote for more than one office twice','So they can collect other delegates’ ballots','So they can skip the Business Session later'],'C','Orientation explains procedures and expectations; correctly marked ballots ensure each delegate’s vote is counted as intended.',WEB),
  q(VD,'Before ILC, from whom should a delegate gather input about issues and candidates?','Members and advisors in their chartered association',['Only the candidates who contact them first','Delegates from rival chartered associations','No one, because the delegate votes privately'],'D','Delegates represent the whole chartered association, so they gather input from its members and advisors before ILC and report back afterward.',WEB),
  q(VD,'Which of these is on the list of ILC sessions voting delegates must attend?','The Recognition Session',['A competitive event awards final','A health care career exhibit','A sponsor tour of the host city'],'A','Delegates attend Voting Delegate Orientation, the Meet the Candidates Breakfast, the Caucus if desired, the Business Session and the Recognition Session.',WEB),
  q(VD,'A delegation agrees that vision and commitment to members will count more than presentation style. Is this appropriate?','Yes, if the delegation agrees and applies it to all',['No, criteria must always be weighted equally','No, only the State Advisor may set any criteria','Yes, but only for candidates from their own state'],'B','Delegations may weight criteria by importance if they agree, as long as the same weighted rubric is applied to every candidate.',WEB),
  q(VD,'What is the main reason a delegate reports back to the chartered association after ILC?','To share results and how decisions were made',['To ask members to redo the official votes','To change votes that were already counted','To announce which candidates they disliked'],'C','Reporting back shares results, decisions and lessons learned, which strengthens trust and helps members understand how HOSA decisions are made.',WEB),
  q(VD,'How long before ILC does HOSA Headquarters send the Voting Delegate Packet to State Advisors?','60 days',['14 days','30 days','90 days'],'D','State Advisors receive the Voting Delegate Packet from HOSA Headquarters 60 days before ILC and share it with their chartered association’s delegates.',WEB),
  q(PP,'A main motion has been made and seconded. What is the next step?','The chair states the question',['Members begin debate at once','The chair puts it to a vote','The maker speaks in favor first'],'A','The six steps are: a member moves, another seconds, the chair states the question, members debate, the chair puts the question and the chair announces the result.',BRIEF),
  q(PP,'How does a presiding officer refer to themself while presiding?','As “the chair”',['As “I, the president”','By their own first name','As “your leader”'],'B','To keep the meeting impersonal, the presiding officer refers to themself as “the chair” rather than using “I” or a personal name.',BRIEF),
  q(PP,'A delegate reaches the microphone to speak. What should they do next?','Address the chair and wait to be recognized',['Begin speaking before others reach a microphone','Address the delegate who spoke just before','Make a motion before saying anything else'],'C','To obtain the floor, a member rises or goes to a microphone, addresses the chair (“Madam President” or “Mr. President”) and waits to be recognized.',BRIEF),
  q(PP,'A motion was laid on the table earlier in the meeting. Which motion resumes it, and by what vote?','Take from the table, by a majority vote',['Reconsider, by a two-thirds vote','Rescind, by a majority with notice','Call for the orders of the day, no vote'],'D','Take from the table resumes consideration of a tabled motion and needs a majority vote.',BRIEF),
  q(PP,'Which motion ranks highest of all in order of precedence?','Fix the time to which to adjourn',['Adjourn','Raise a question of privilege','Call for the orders of the day'],'A','From highest to lowest: fix the time to which to adjourn, adjourn, recess, question of privilege, orders of the day, lay on the table, previous question and so on.',BRIEF),
  q(PP,'An amendment is pending. Which of these motions may still be made?','Previous question',['Postpone indefinitely','A new main motion','Another main motion to buy supplies'],'B','While a motion is pending, only higher-ranking motions may be made. The previous question ranks above amend; postpone indefinitely and main motions rank below it.',BRIEF),
  q(PP,'A member appeals the chair’s ruling, and the vote on the appeal is tied. What happens?','The chair’s ruling is sustained',['The chair’s ruling is reversed','The vote is retaken by ballot','The appeal is referred to committee'],'C','An appeal needs a second, and a tie vote sustains the chair, because a majority is needed to overturn the chair’s ruling.',BRIEF),
  q(PP,'A member raises a point of order. Does it need a second?','No; the chair rules on it',['Yes; it needs a second','Yes; it needs two seconds','No; the assembly votes'],'D','A point of order claims a rule is being broken; it needs no second, and the chair rules on it, subject to appeal.',BRIEF),
  q(PP,'A majority-vote motion receives 52 yes, 48 no and 20 abstentions. What is the result?','Adopted, because 52 is more than half of 100 votes cast',['Lost, because 52 is not more than half of 120','Lost, because abstentions are counted as no votes','Tied, because abstentions are split evenly'],'A','A majority is more than half of the votes cast, excluding abstentions and blanks. 100 votes were cast, and 52 is more than half of them.',BRIEF),
  q(PP,'Without previous notice, what vote does a motion to rescind an earlier action require?','Two-thirds, or a majority of the entire membership',['A simple majority of those voting','Unanimous consent of all members who are present','A plurality of the votes cast'],'B','Rescind or amend something previously adopted needs two-thirds, a majority with previous notice or a majority of the entire membership.',BRIEF),
  q(PP,'A member wants to bring back a motion that was decided at a meeting two weeks ago. Is reconsider available?','No; reconsider applies to votes taken the same day',['Yes; reconsider can be used at any later time','Yes; but only by the member who made it','No; decided motions can never be changed'],'C','Reconsider brings back a motion decided the same day and is moved by a member of the prevailing side; to change an earlier decision, use rescind or amend.',BRIEF),
  q(PP,'Which pair of principles does parliamentary procedure balance?','Majority rule and the rights of the minority',['Speed of decisions and the chair’s preferences','Unanimity and silence of those opposed','Officer authority and members’ obedience'],'D','Parliamentary procedure protects majority rule while respecting minority rights, takes one item at a time and ensures full and free discussion.',BRIEF),
  q(INC,'What is the main purpose of a nonprofit’s financial reports?','To show how resources were actually used',['To list members by chapter and division','To replace the bylaws for the next year','To announce profits paid to its owners'],'A','Financial reports, along with budgets and audits, let the board and members see how money was used, supporting fiduciary responsibility.',HB),
  q(INC,'A board member’s company bids on a contract with the nonprofit. What is the best practice?','Disclose the interest and stay out of the decision',['Vote first, since they know the company best','Keep the link private to avoid any confusion','Let staff approve it without the board’s review'],'B','Conflict-of-interest policies protect the organization; the member discloses the relationship and does not take part in the decision.',HB),
  q(INC,'Which example best shows transparency in a nonprofit organization?','Sharing meeting decisions and budgets with members',['Holding all board votes in secret sessions','Letting one officer approve all spending','Keeping audit results from the members'],'C','Ethical governance includes transparency, accountability and decisions that serve members; open sharing of decisions and finances is transparency.',HB),
  q(INC,'An organization’s standing policy conflicts with its bylaws. Which one applies?','The bylaws',['The policy, since it is newer','Whichever the chair prefers','The policy, if staff wrote it'],'D','Higher-level rules take precedence: laws, then the charter, bylaws, special rules of order, the parliamentary authority and finally standing rules and policies.',HB),
  q(INC,'A bylaw provision conflicts with state law. Which one applies?','The state law',['The bylaw, since members adopted it','Whichever was written more recently','The bylaw, if the board agrees'],'A','Applicable laws sit at the top of the hierarchy, above the corporate charter, the bylaws and all other rules of an organization.',HB),
  q(INC,'Why do bylaw amendments usually require previous notice?','So members know the exact change before voting',['So the chair can approve it in private','So the change can skip the voting stage','So only officers learn of the proposal'],'B','Bylaws are usually amended with previous notice and a two-thirds vote, giving members time to study the exact proposed wording before deciding.',HB),
  q(INC,'How do standing rules differ from special rules of order?','Standing rules cover administrative matters',['Standing rules outrank the bylaws','Standing rules govern debate and motions','Standing rules can never be changed'],'C','Special rules of order deal with parliamentary procedure and rank above the parliamentary authority; standing rules and policies cover administration and rank lowest.',BRIEF),
  q(INC,'Who carries out a nonprofit board’s decisions in daily operations?','The staff, under the board’s direction',['The voting delegates, between conferences','The sponsors, through their contracts','The auditors, after each fiscal year'],'D','The board governs and is responsible for legal and financial health, while staff carry out daily operations under the board’s direction.',HB),
  q(ORG,'How do members’ voices reach the international level of HOSA?','Through voting delegates and student officers',['Only through sponsors of competitive events','Only through HOSA Headquarters surveys','Only through each chapter advisor’s vote'],'A','Information flows both ways: Headquarters communicates to State Advisors and chapters, while members’ voices reach the international level through delegates and officers.',HB),
  q(ORG,'Who usually leads a chartered association?','A State Advisor and state officers',['A chapter advisor and chapter officers','The Executive Council president alone','A panel of competitive event judges'],'B','Chartered associations, typically states, are led by State Advisors and state officers and hold State Leadership Conferences.',HB),
  q(ORG,'A local chapter joins HOSA. With which groups does it affiliate?','Its chartered association and the international organization',['Only its school’s parent-teacher group','Only another chapter in the same city or county school district','Only the sponsors of its chosen events'],'C','Students join through a local chapter, which affiliates with its chartered association and the international organization, with dues paid as required.',HB),
  q(ORG,'Where can a member find which divisions may enter a particular competitive event?','In that event’s competitive event guidelines',['In the Voting Delegate Packet','In the minutes of the last chapter meeting','In the chartered association budget'],'D','Competitive event guidelines specify eligible divisions; for example, Organizational Leadership is for secondary and postsecondary/collegiate members.',HB),
  q(ORG,'In schools and colleges, HOSA works alongside which kind of program?','Health science education programs',['Athletic training clubs','Student government councils','National honor society chapters'],'A','HOSA is a career and technical student organization that works with health science education programs in schools and colleges.',HB),
  q(ORG,'Who leads HOSA at the international level?','HOSA Headquarters staff and the Executive Council',['The largest chartered association each year','A rotating group of chapter advisors','The sponsors of the competitive events'],'B','HOSA Headquarters staff manage international operations, while the Executive Council serves as the international student officer team.',HB),
  q(HIST,'According to HOSA’s mission, its members become leaders in which community?','The global health community',['The national sports community','Their local business community','The world finance community'],'C','HOSA’s mission is to empower HOSA-Future Health Professionals to become leaders in the global health community through education, collaboration and experience.',HB),
  q(HIST,'How has ILC served HOSA since its early conferences?','As the yearly gathering where states send competitors and delegates',['As a one-time event held only in 1976','As a meeting held only for HOSA staff','As a conference held every ten years to rewrite the bylaws'],'D','HOSA’s first conferences grew into the International Leadership Conference, which brings members together each year with competitors and voting delegates.',FFY),
  q(HIST,'Beyond competitive events, what did HOSA’s programs grow to include over time?','Leadership development, service projects, scholarships and recognition',['Paid hospital jobs, licensing exams and residency programs','Sports leagues, travel clubs and social events only','Fundraising contests run for sponsors and vendors only'],'A','HOSA’s programs expanded to include many competitive events, leadership development, service projects, scholarships and recognition programs.',FFY),
  q(HIST,'Which students did HOSA first serve when it was founded?','Students in health occupations education programs',['Students in medical school residency programs','Students in college athletic programs','Practicing nurses in hospital programs'],'B','HOSA was founded in 1976 for students in health occupations and health science education programs, giving them leadership development and career preparation.',FFY),
  q(HIST,'A timeline shows founding in 1976, new divisions added and the adoption of the name HOSA-Future Health Professionals. What does it suggest?','HOSA’s reach and identity broadened over time',['HOSA narrowed its focus to one career only','HOSA stopped holding its yearly conference','HOSA changed its founding year at some point'],'C','New divisions and the name HOSA-Future Health Professionals, chosen to reflect all health careers, show an organization that broadened its reach over five decades.',FFY),
  q(HIST,'What does the expansion of chartered associations in HOSA’s history describe?','More states and similar units joining HOSA',['Fewer chapters being chartered each year','The merger of HOSA with other CTSOs','The closing of the international office'],'D','Expansion of chartered associations, typically states or similar units, is one of the growth milestones recorded in The First Fifty Years 1976–2026.',FFY),
  q(EC,'Besides presiding, what other kinds of duties may Executive Council positions carry?','Representing regions or divisions, communications or records',['Grading tests and judging every competitive event','Writing state bylaws and setting dues for every chapter','Selecting voting delegates for each state'],'A','The Handbook and bylaws list each position: a president who presides and leads, plus officers with duties such as representing regions or divisions, communications or records.',HB),
  q(EC,'A candidate has always met deadlines and kept promises as a chapter officer. Which quality does this show?','Reliability',['Popularity','Visibility','Charisma'],'B','Effective student officers show servant leadership, communication skills, knowledge of HOSA, reliability, teamwork, professionalism and a clear vision.',HB),
  q(EC,'Which activity best fits the Executive Council’s role?','Promoting HOSA and modeling leadership for members',['Choosing the winners of competitive events','Running each chartered association’s budget','Electing state officers in every state'],'C','Executive Council officers represent members, promote HOSA, help lead conference activities, communicate with chartered associations and model leadership.',HB),
  q(EC,'Which candidate answer best shows a clear vision for serving members?','A specific plan to expand member resources this year',['A promise to be the most popular officer','A list of the candidate’s favorite events at past conferences','A request for votes from friends only'],'D','A clear vision for serving members is one quality delegates use to evaluate candidates, alongside experience, knowledge of HOSA and communication.',HB),
  q(MEM,'How do students usually join HOSA and complete membership?','Through a local chapter, with dues paid as required',['By applying directly to the Executive Council','By passing the Voting Delegate Test first','By registering for ILC without a chapter'],'A','Students typically join through a local chapter, which affiliates with its chartered association and the international organization, with dues paid as required.',HB),
  q(MEM,'Which statement about postsecondary/collegiate members is correct?','They are active student members',['They are professional members only','They may not compete in events','They belong to the alumni division'],'B','Active student divisions are middle school, secondary and postsecondary/collegiate; alumni and professional members support students.',HB)
 ],8942)
};
